def comps(mask):
 seen=np.zeros_like(mask);out=[]
 for y,x in zip(*np.where(mask)):
  if seen[y,x]:continue
  stack=[(int(y),int(x))];seen[y,x]=True;xy=[]
  while stack:
   py,px=stack.pop();xy.append([px,py])
   for dy in (-1,0,1):
    for dx in (-1,0,1):
     yy,xx=py+dy,px+dx
     if 0<=yy<mask.shape[0]and 0<=xx<mask.shape[1]and mask[yy,xx]and not seen[yy,xx]:seen[yy,xx]=True;stack.append((yy,xx))
  out.append(xy)
